/**
 * Gtk4\GDateTime::get_ymd(): array
 *
 * Retrieves the Gregorian day, month, and year of a given #GDateTime.
 */
ZEND_METHOD(Gtk4_GDateTime, get_ymd) {
  ZEND_PARSE_PARAMETERS_NONE();
  GDateTime *self = PHPGTK_BOXED_SELF(GDateTime);
  gint year = 0;
  gint month = 0;
  gint day = 0;
  g_date_time_get_ymd(self, &year, &month, &day);
  array_init_size(return_value, 3);
  {
    zval item;
    ZVAL_LONG(&item, static_cast<zend_long>(year));
    add_next_index_zval(return_value, &item);
  }
  {
    zval item;
    ZVAL_LONG(&item, static_cast<zend_long>(month));
    add_next_index_zval(return_value, &item);
  }
  {
    zval item;
    ZVAL_LONG(&item, static_cast<zend_long>(day));
    add_next_index_zval(return_value, &item);
  }
}

