namespace phpgtk {
// MINIT: bind the PHP class to G_TYPE_DATE_TIME with its field table.
void register_GDateTime(zend_class_entry *ce) {
  register_boxed(BoxedClass{
      .type = G_TYPE_DATE_TIME,
      .ce = ce,
      .fields = fields,
      .read = read,
      .write = write,
      // NOLINTBEGIN(cppcoreguidelines-pro-type-const-cast) g_date_time_equal() takes non-const
      // operands
      .equal =
          [](gconstpointer a, gconstpointer b) {
            return g_date_time_equal(static_cast<GDateTime *>(const_cast<gpointer>(a)),
                                     static_cast<GDateTime *>(const_cast<gpointer>(b))) != FALSE;
          }
      // NOLINTEND(cppcoreguidelines-pro-type-const-cast)
  });
}
}  // namespace phpgtk
